// ---------------------------------------------------------------- "Race"
bool bind_race(kern::logic::Runtime& logic) {
  const bool runs = g_race.bind(logic);
  g_gate_rows.clear();
  g_gates.clear();
  kGates = 0;
  kRaceLaps = static_cast<i32>(::sc::lowered::fits<int>(g_race.get<f64>("RaceLaps")));
  kCourseScale = static_cast<f32>(g_race.get<f64>("CourseScale"));
  const i32 n = static_cast<i32>(g_race.get<std::vector<GateRow>>("Gates").size());
  if (!runs || n < 2) return false;
  for (i32 i = 0; i < n; ::sc::lowered::pre_inc(i)) { ::sc::lowered::tick();  // (each gate as it stands in the world: the Blueprint's GateAt)
    GateRow g;
    g_race.call("GateAt", std::tie(g), i);
    g_gate_rows.push_back(g);
  }
  for (const GateRow& g : g_gate_rows) g_gates.push_back({g.name, g.center, static_cast<f32>(g.width), static_cast<f32>(g.height), g.start});
  kGates = static_cast<i32>(g_gates.size());
  return true;
}

const Gate& gate(i32 i) { return kGates > 0 ? ::sc::converted::at(g_gates, static_cast<std::size_t>(::sc::lowered::rem((::sc::lowered::plus((::sc::lowered::rem(i, kGates)), kGates)), kGates))) : kNoGate; }

void gate_axes(i32 i, Vec2& normal, Vec2& right) {
  Vec3 n, r;
  g_race.call("GateAxes", std::tie(n, r), i);
  normal = {n.x, n.y};
  right = {r.x, r.y};
}

