      ::sc::lowered::draw_pair(draw, ::sc_old_combat_rules::sc::combat::kSoldierHp, ::sc_new_combat_rules::sc::combat::kSoldierHp);
      ::sc::lowered::draw_pair(draw, ::sc_old_combat_rules::sc::combat::kMilHit, ::sc_new_combat_rules::sc::combat::kMilHit);
      ::sc::lowered::draw_pair(draw, ::sc_old_combat_rules::sc::combat::kHeliHp, ::sc_new_combat_rules::sc::combat::kHeliHp);
